// ?format=geo -> map boundaries; ?format=json -> the data; otherwise the page with the data injected
const q = $('Audit Page').first().json.query || {};
if (q.format === 'geo') return [{ json: { body: $input.first().json.data, type: 'application/json; charset=utf-8', cache: 'public, max-age=86400' } }];
const rows = $('Load Results').all().map(i => i.json).filter(r => r.source_id);
const runs = $('Load Runs').all().map(i => i.json).filter(r => r.id);
const projects = $('Load Projects').all().map(i => i.json).filter(p => p.id);
if (q.format === 'json') return [{ json: { body: JSON.stringify({ projects, rows, runs }), type: 'application/json; charset=utf-8', cache: 'no-store' } }];
const safe = (x) => JSON.stringify(x).replace(/</g, '\\u003c');
const html = $input.first().json.data.replace('/*__DATA__*/[]', safe(rows)).replace('/*__RUNS__*/[]', safe(runs)).replace('/*__PROJECTS__*/[]', safe(projects)).replace('/*__READ_ONLY__*/false', 'true');
return [{ json: { body: html, type: 'text/html; charset=utf-8', cache: 'no-store' } }];

// a decision on a PROJECT (project_id; the audit page) or, from older pages, on one source's result (extraction_id)
const b = $input.first().json.body || {};
const pid = Number(b.project_id || 0), eid = Number(b.extraction_id || 0);
const decision = String(b.decision || '');
if (!(Number.isInteger(pid) && pid > 0) && !(Number.isInteger(eid) && eid > 0)) throw new Error('bad project_id');
if (!['approved', 'rejected'].includes(decision)) throw new Error('decision must be approved or rejected');
return [{ json: { pid, eid, decision, comment: String(b.comment || '').slice(0, 2000), reviewer: String(b.reviewer || '').slice(0, 100) } }];

const b = $input.first().json.body || {};
const action = String(b.action || ''), target = String(b.target || '').trim().toUpperCase();
const id = Number(b.source_id || 0), from = String(b.project || '').trim().toUpperCase();
if (!['detach', 'move', 'merge'].includes(action)) throw new Error('action must be detach, move or merge');
if (action === 'merge' ? !/^P-\d{5}$/.test(from) : !(Number.isInteger(id) && id > 0)) throw new Error('bad source or project');
if (action !== 'detach' && !/^P-\d{5}$/.test(target)) throw new Error('target must look like P-00012');
if (action === 'merge' && from === target) throw new Error('a project cannot be merged into itself');
return [{ json: { id, action, target, from, reviewer: String(b.reviewer || '').slice(0, 100) } }];

const b = $input.first().json.body || {};
const ids = [...new Set((Array.isArray(b.source_ids) ? b.source_ids : [b.source_id]).map(Number).filter(n => Number.isInteger(n) && n > 0))].slice(0, 30);
if (!ids.length) throw new Error('no source ids');
return [{ json: { ids, reviewer: String(b.reviewer || '').slice(0, 100), started_at: new Date().toISOString(), job_id: String(b.job_id || '') } }];

const b = $input.first().json.body || {};
const domain = String(b.domain || '').replace(/[^a-z_]/g, '');
return [{ json: { domain, limit: Math.min(300, Math.max(1, Number(b.limit) || 100)), min_relevance: Number(b.min_relevance) || 0.6, job_id: String(b.job_id || '') } }];

const b = $input.first().json.body || {};
const ids = [...new Set((Array.isArray(b.project_ids) ? b.project_ids : []).map(Number).filter(n => Number.isInteger(n) && n > 0))].slice(0, 100);
return [{ json: { ids, job_id: String(b.job_id || '') } }];
